const logo=o=>{const ks=Object.keys(LOGO_IMG).filter(k=>o.includes(k));if(ks.length)return `<div class="lgs">${ks.map(k=>`<div class="lg c3"><img src="${LOGO_IMG[k]}" alt="${k} logo" width="56" height="56" loading="lazy" decoding="async"></div>`).join("")}</div>`;const n=o.split(",")[0].trim();let h=0;for(const c of n)h=(h*31+c.charCodeAt(0))%360;const w=n.split(" "),t=w.length>1?w[0][0]+w[1][0]:n.slice(0,2);return `<div class="lgs"><div class="lg c3" style="background:hsl(${h} 45% 36%)" role="img" aria-label="${n} logo"><span>${t.toUpperCase()}</span></div></div>`};
