const tools=(t,a,c)=>{const p=chunk(a,8);return `<div class="car"><div class="hd"><h2>${ic(t=="AI Tools"?"ai":"plat")}${t}</h2><div class="ctl"><span class="cnt">1/${p.length}</span><button data-d="-1" aria-label="Previous ${t}">&#8592;</button><button data-d="1" aria-label="Next ${t}">&#8594;</button></div></div><div class="pg">${p.map(g=>dots(g,c)).join("")}</div></div>`};
const embed=u=>{let m;if(/^\s*</.test(u))return `<div class="vid emb">${u}</div>`;if(m=u.match(/(?:youtu\.be\/|v=|embed\/)([\w-]{11})/))return `<iframe class="vid" src="https://www.youtube.com/embed/${m[1]}" title="Welcome video" allow="fullscreen;picture-in-picture" allowfullscreen></iframe>`;if(m=u.match(/vimeo\.com\/(\d+)/))return `<iframe class="vid" src="https://player.vimeo.com/video/${m[1]}" title="Welcome video" allow="fullscreen;picture-in-picture" allowfullscreen></iframe>`;return `<video class="vid" src="${u}" controls playsinline></video>`};
const vid=t=>`<section class="card"><h2>${ic("video")}${t}</h2>${VIDEO_URL?`<button type="button" class="vid vph vfac" data-vid aria-label="Play welcome video"><span class="play">&#9654;</span><p>Watch the welcome video</p></button>`:`<div class="vid vph"><div class="play">&#9654;</div><p>Welcome video coming soon</p></div>`}</section>`;
const media=u=>/^\s*</.test(u)||/youtu|vimeo|\.(mp4|webm)(\?|$)/i.test(u)?embed(u):`<img src="${u}" alt="Project" loading="lazy">`;
const proj=(u,i)=>u?`<div class="ph pj">${media(u)}</div>`:`<div class="ph">Project ${i+1}: add image</div>`;
function countUp(el){const v=+el.dataset.v;let s=null;const f=t=>{s=s??t;const p=Math.min((t-s)/1100,1);el.textContent=Math.round(v*p)+"%";if(p<1)requestAnimationFrame(f)};requestAnimationFrame(f)}
