const post=i=>{const b=BLOGS[+i];if(!b)return V.blog();return `<a href="#blog" style="color:var(--mute);text-decoration:none">&larr; All posts</a><section class="card hero" style="margin-top:10px"><p class="eb">${b.cat}</p><h1>${b.title}</h1>${b.date?`<p class="sub">${b.date}</p>`:""}<p class="sub">${b.text}</p></section>`};
const V={blog:()=>`<h1>Blog</h1><div class="tiles">${BLOGS.map(blogBox).join("")}</div>`,
dashboard:()=>`<div class="hero2"><p class="eb">Your knowledge deserves a bigger stage</p><h1>Turn your expertise<br>into <span class="rslot"><b class="rw">online courses</b><b class="rw">websites</b><b class="rw">sales funnels</b><b class="rw">eBooks</b><b class="rw">AI videos</b><b class="rw">social content</b></span></h1><p class="sub3">Great ideas shouldn't stay stuck in your head. Let's shape what you know into something people can find, trust and happily pay for.</p></div><div class="grid"><div class="col">${vid("Meet VA Carlo G.")}<section class="card"><h2>${ic("skill")}Skills & Expertise</h2>${skills()}</section></div>
<div class="col"><section class="card"><h2>${ic("user")}About Me</h2><p style="margin:0 0 10px;font-size:14px">${ABOUT[0]}</p><a href="/about.html">Read more</a></section><section class="card"><h2>${ic("edu")}Education</h2>${eduList()}</section></div></div><section class="card" style="margin-top:18px">${mq("Platforms",PLATFORMS,"plat")}</section><section class="card" style="margin-top:18px">${mq("AI Tools",AI,"ai")}</section><section class="card" style="margin-top:18px">${slides(false)}</section>`,
about:()=>`<h1>About VA Carlo G.</h1><div class="abt">${PHOTO?`<img class="pf" src="${PHOTO}" alt="VA Carlo G." width="200" height="200" decoding="async">`:"<div class='pf'></div>"}<div class="col">${vid("Meet VA Carlo G.")}<section class="card">${ABOUT.map(p=>`<p style="margin:0 0 16px">${p}</p>`).join("")}</section></div></div>`,
education:()=>`<h1>Education</h1><div class="col" style="max-width:720px">${EDU.map(e=>`<section class="card">${eduRow(e)}</section>`).join("")}<section class="card"><h2>Licenses & Certifications</h2><ul style="margin:0;padding-left:18px">${CERTS.map(c=>`<li>${c}</li>`).join("")}</ul></section></div>`,
work:()=>`<h1>Work Experience</h1><section class="card">${slides(true)}</section>`,
platforms:()=>`<h1>Platforms & Tools</h1><section class="card">${dots(PLATFORMS,"d3")}</section>`,
ai:()=>`<h1>AI Tools</h1><section class="card">${dots(AI,"d3")}</section>`,
contact:()=>`<h1>FAQs / Contact</h1><section class="card cp2 faqc" id="faq"><p class="eb">FAQs</p><h2>Quick answers about my services</h2><div class="th" role="log" aria-label="Conversation"></div><div class="chips"></div></section><section class="card cp2" style="margin-top:18px"><p class="eb">Send a message</p><h2>Tell me about your project</h2><p class="sub2">Fill in the form and your message goes straight to me.</p><iframe class="cal" style="height:640px" src="https://tally.so/embed/o9evD1?alignLeft=1&hideTitle=1&transparentBackground=1&dynamicHeight=1" title="Contact form" loading="lazy"></iframe><p class="sub2">Form not loading? <a href="https://tally.so/r/o9evD1" target="_blank" rel="noopener">Open it in a new tab</a>.</p></section><section class="card cp2" style="margin-top:18px"><p class="eb">Book a call</p><h2>Pick a time that works for you</h2><p class="sub2">Choose a date and time below and we'll meet to talk about your project.</p><iframe class="cal" src="${CALENDLY}?hide_gdpr_banner=1" title="Book a call with VA Carlo G." loading="lazy"></iframe><p class="sub2">Calendar not loading? <a href="${CALENDLY}" target="_blank" rel="noopener">Open it in a new tab</a>.</p></section>`,
services:()=>`<h1>Services</h1><div class="tiles">${SERVICES.map(([k,n])=>`<a class="card tile" href="/services/${SLUGS[k]}.html"><b>${n}</b><em>See my works</em></a>`).join("")}</div>`
};
const COURSE_HERO=`<section class="card hero" style="margin-top:10px"><p class="eb">E-learning</p><h1>Your knowledge is worth more than one hour at a time.</h1><p class="sub">I design and build professional online academies for coaches, consultants, and educators &mdash; from first lesson to first enrolment. Two specialist programmes. One certified partner.</p><p style="margin:16px 0 8px"><a class="btn cb-btn " href="https://tally.so/r/o9evD1?service=Online%20Course%20Builder%20%26%20Instructional%20Design" target="_blank" rel="noopener noreferrer">Book a Strategy Call</a></p><p class="cb-note">The strategy call is free and there&rsquo;s no pressure to move forward.</p></section>`;const COURSE_BODY=`<section class="cb-sec"><p class="eb">The real problem</p><h2 class="cb-h">Your expertise is worth far more than one client at a time will ever pay you.</h2><p class="cb-sub">The knowledge you have built over years of practice could transform hundreds of people. But packaged into 1:1 hours, it reaches one person at a time — and your income has a ceiling that no amount of effort can break through. An online academy removes that ceiling permanently.</p><div class="cb-grid"><div class="card cb-card"><span class="cb-n">01</span><h3>Your income stops when you stop working</h3><p>Every pound or dollar of revenue requires an hour of your time. A well-built online course sells around the clock — while you sleep, travel, and serve other clients.</p></div><div class="card cb-card"><span class="cb-n">02</span><h3>The technology is overwhelming and time-consuming</h3><p>LearnWorlds, curriculum architecture, student journeys, payment flows, and automation — the technical side alone stops most course creators before they even start.</p></div><div class="card cb-card"><span class="cb-n">03</span><h3>Your existing academy is not converting or completing</h3><p>Low enrolment rates, students who disappear after lesson one, and revenue that has plateaued — these are design problems, not content problems.</p></div><div class="card cb-card"><span class="cb-n">04</span><h3>The student experience does not match your expertise</h3><p>You have built exceptional knowledge. Your academy should reflect that. A generic platform setup undermines the trust your content has earned.</p></div></div></section><section class="cb-sec"><p class="eb">Two specialist programmes</p><h2 class="cb-h">Start from zero or scale what you've already built.</h2><p class="cb-sub">Both programmes are delivered on LearnWorlds by a certified specialist. The right one depends entirely on where your academy is today.</p><div class="cb-two"><div class="card cb-prog"><span class="cb-tag">Academy Foundation</span><h3 class="cb-ph">Build your academy from the ground up.</h3><p class="cb-sub" style="font-size:14.5px">You have expertise, ideas, or a rough course structure — but no live academy yet. Academy Foundation takes you from concept to a fully configured, professionally designed LearnWorlds academy that is ready to enroll its first students.</p><p class="cb-for">For first-time course creators</p><ul class="cb-ul ck"><li>Course curriculum design and module architecture</li><li>Full LearnWorlds platform setup and configuration</li><li>Branded academy pages — home, course, checkout, and confirmation</li><li>Learning path design and student progression logic</li><li>Quiz, assignment, and certificate builder setup</li><li>Payment processing and pricing tier configuration</li><li>Enrolment email automation and student onboarding sequence</li><li>Mobile-optimised student experience across all devices</li><li>Pre-launch strategy and sales page copywriting</li></ul><p style="margin:16px 0 0"><a class="btn cb-btn " href="https://tally.so/r/o9evD1?service=Online%20Course%20-%20Academy%20Foundation" target="_blank" rel="noopener noreferrer">Book Academy Foundation</a></p></div><div class="card cb-prog"><span class="cb-tag">Academy Growth Engine · Monthly Retainer</span><h3 class="cb-ph">Scale your academy beyond its current ceiling.</h3><p class="cb-sub" style="font-size:14.5px">You already have a LearnWorlds academy — but enrolments are lower than they should be, completion rates are disappointing, or revenue has plateaued. Growth Engine audits, optimises, and scales what you have built into a high-performing, revenue-generating system.</p><p class="cb-for">For existing academies ready to scale</p><ul class="cb-ul ck"><li>Comprehensive LearnWorlds academy audit and gap analysis</li><li>Conversion rate optimisation for enrolment and checkout pages</li><li>Student engagement strategy and completion rate improvement</li><li>Monthly live workshop and group coaching integration</li><li>Content asset creation — workbooks, resource libraries, and guides</li><li>Funnel optimisation connecting your audience to course enrolment</li><li>Upsell, cross-sell, and post-purchase sequence setup</li><li>Affiliate or referral programme configuration</li><li>Monthly performance reporting and strategic refinement</li></ul><p style="margin:16px 0 0"><a class="btn cb-btn " href="https://tally.so/r/o9evD1?service=Online%20Course%20-%20Academy%20Growth%20Engine" target="_blank" rel="noopener noreferrer">Book Academy Growth Engine</a></p></div></div></section><section class="cb-sec"><p class="eb">Why LMS Platform</p><h2 class="cb-h">The platform built for serious educators.</h2><p class="cb-sub">Not all course platforms are equal. LearnWorlds is engineered specifically for professional educators, coaches, and course creators who need more than a basic video host — it is a complete academy-grade learning environment.</p><p class="cb-sub">As an Online Course Builder and Instructional Design Specialist, every academy I build is configured from the ground up for maximum student engagement, completion, and revenue — not minimum viable functionality.</p><div class="cb-grid"><div class="card cb-card"><span class="cb-n">01</span><h3>Interactive Video Learning</h3><p>Embed quizzes, questions, and calls-to-action directly inside video lessons — students engage actively, not passively.</p></div><div class="card cb-card"><span class="cb-n">02</span><h3>Advanced Analytics &amp; Reporting</h3><p>Track completion rates, time-on-lesson, quiz scores, and revenue per student with built-in dashboards that tell you exactly what is and is not working.</p></div><div class="card cb-card"><span class="cb-n">03</span><h3>Fully Custom Branded Pages</h3><p>Every page — course catalogue, student dashboard, checkout, and certificates — is fully customisable to match your brand and reflect your professional standard.</p></div><div class="card cb-card"><span class="cb-n">04</span><h3>Certificates, Badges &amp; Gamification</h3><p>Completion certificates, achievement badges, leaderboards, and milestone systems that drive student motivation and dramatically improve course completion rates.</p></div><div class="card cb-card"><span class="cb-n">05</span><h3>Built-in Automation &amp; Email</h3><p>Automated enrolment emails, drip content unlocking, re-engagement triggers, and upsell sequences — all configured from inside one platform.</p></div><div class="card cb-card"><span class="cb-n">06</span><h3>Flexible Pricing &amp; Monetisation</h3><p>One-time, subscription, payment plan, bundle, and coupon pricing — every monetisation model a professional academy needs, fully supported.</p></div></div></section><section class="cb-sec"><p class="eb">What's included</p><h2 class="cb-h">Strategy, design, and build. All of it handled.</h2><p class="cb-sub">Both programmes cover every phase end to end — nothing is handed back half-finished for you to figure out.</p><div class="cb-grid cb-inc"><div class="card cb-card"><h3>Curriculum &amp; Learning Strategy</h3><ul class="cb-ul"><li>Course structure mapping — modules, lessons, and learning outcomes</li><li>Curriculum design aligned to your student's transformation goal</li><li>Content type planning — video, text, quizzes, PDFs, and assignments</li><li>Learning path logic and lesson prerequisite configuration</li><li>Pricing strategy and tier structure recommendation</li><li>Student success metrics definition and tracking setup</li></ul></div><div class="card cb-card"><h3>Brand &amp; Page Design</h3><ul class="cb-ul"><li>Academy home page — fully branded and conversion-optimised</li><li>Course landing page designed to convert visitors into students</li><li>Checkout page with trust signals and seamless payment flow</li><li>Student dashboard and course player branding</li><li>Certificate design and achievement badge artwork</li><li>Mobile-optimised layout across all academy pages</li></ul></div><div class="card cb-card"><h3>Technical Build &amp; Integration</h3><ul class="cb-ul"><li>Full LearnWorlds platform setup and configuration</li><li>Payment processor integration (Stripe, PayPal)</li><li>Email automation — welcome, onboarding, and progress sequences</li><li>Quiz, assignment, and certificate builder configuration</li><li>CRM, email platform, and funnel tool integration</li><li>Analytics and tracking — Google Analytics plus LW reporting</li></ul></div><div class="card cb-card"><h3>Launch &amp; Marketing</h3><ul class="cb-ul"><li>Course sales funnel — lead magnet, landing page, and email sequence</li><li>Pre-launch waitlist page and social campaign strategy</li><li>Sales page copywriting using proven conversion frameworks</li><li>Email launch sequence — pre-launch, cart open, and close</li><li>Social media content for the launch period</li><li>30-day post-launch optimisation review</li></ul></div><div class="card cb-card"><h3>Content Assets &amp; Resources</h3><ul class="cb-ul"><li>Course workbook or companion PDF design and layout</li><li>Lesson slide deck templates — branded Canva or PowerPoint masters</li><li>Resource library setup and downloadable file organisation</li><li>Quiz question design and answer logic configuration</li><li>Assignment brief writing and submission setup</li><li>Bonus module and resource section configuration</li></ul></div><div class="card cb-card"><h3>Growth &amp; Optimisation <span class="cb-tag sm">Growth Engine</span></h3><ul class="cb-ul"><li>Full academy audit — conversion, completion, and revenue gap analysis</li><li>Monthly live group coaching or workshop integration</li><li>Upsell, cross-sell, and premium tier configuration</li><li>Re-engagement automation for inactive or dropped-off students</li><li>Affiliate or referral programme setup and management</li><li>Monthly performance review and strategy refinement</li></ul></div></div></section><section class="cb-sec"><p class="eb">Investment</p><h2 class="cb-h">Why Choose Me?</h2><p class="cb-sub">Unlike traditional freelancers who specialize in only one area, I combine expertise across marketing, automation, design, content, and technology to deliver a complete academy solution.</p><div class="cb-tw"><table class="cb-t"><thead><tr><th>Feature</th><th>🇺🇸 Typical US Freelancer/Agency</th><th>🇦🇺 Typical AU Freelancer/Agency</th><th class="us">🚀 VA Carlo G.</th></tr></thead><tbody><tr><th scope="row">Average One-Time Project</th><td>$9,500–$15,000</td><td>$10,000–$12,000</td><td class="us">Starts at $1599</td></tr><tr><th scope="row">LearnWorlds setup from scratch</th><td>✔</td><td>✔</td><td class="us">✔ Included</td></tr><tr><th scope="row">Curriculum &amp; learning pathway design</th><td>Sometimes</td><td>Sometimes</td><td class="us">✔ Included</td></tr><tr><th scope="row">Branded academy page design</th><td>✔</td><td>✔</td><td class="us">✔ Included</td></tr><tr><th scope="row">Course sales page copywriting</th><td>Usually Additional</td><td>Usually Additional</td><td class="us">✔ Included</td></tr><tr><th scope="row">Payment gateway &amp; pricing configuration</th><td>✔</td><td>✔</td><td class="us">✔ Included</td></tr><tr><th scope="row">Student onboarding automation</th><td>Often Additional</td><td>Often Additional</td><td class="us">✔ Included</td></tr><tr><th scope="row">Quiz, assignments &amp; certificates</th><td>✔</td><td>✔</td><td class="us">✔ Included</td></tr><tr><th scope="row">Course migration from another platform</th><td>Additional Service</td><td>Additional Service</td><td class="us">✔ Included</td></tr><tr><th scope="row">Basic SEO for academy pages</th><td>Usually Additional</td><td>Usually Additional</td><td class="us">✔ Included</td></tr><tr><th scope="row">AI-assisted content workflow</th><td>Rare</td><td>Rare</td><td class="us">✔ Included</td></tr><tr><th scope="row">Marketing strategy consultation</th><td>Separate Service</td><td>Separate Service</td><td class="us">✔ Included</td></tr><tr><th scope="row">Funnel recommendations</th><td>Separate Service</td><td>Separate Service</td><td class="us">✔ Included</td></tr><tr><th scope="row">Analytics dashboard setup</th><td>Sometimes</td><td>Sometimes</td><td class="us">✔ Included</td></tr><tr><th scope="row">Standard operating procedures (SOPs)</th><td>Rare</td><td>Rare</td><td class="us">✔ Included</td></tr><tr><th scope="row">Technical support after launch</th><td>Limited</td><td>Limited</td><td class="us">✔ Included</td></tr></tbody></table></div></section><section class="cb-sec"><p class="eb">Common questions</p><h2 class="cb-h">Answered before you ask.</h2><div class="cb-faq"><details class="card cb-q"><summary>Do I need a LearnWorlds account before we start?</summary><p>No — you do not need an existing LearnWorlds account. During the strategy call, I will recommend the right plan tier for your needs and scale. If you already have an account and an existing academy, that is ideal for the Growth Engine programme — I begin with a full audit of what you have built.</p></details><details class="card cb-q"><summary>Do I need to have my course content recorded before we start?</summary><p>Not necessarily. The Academy Foundation programme includes full curriculum design — which means I plan the module structure, lesson content requirements, and video briefs before you record anything. You will know exactly what to film, how long each lesson should be, and what format to use. Having some content ready speeds things up, but it is not a prerequisite for starting.</p></details><details class="card cb-q"><summary>How long does a full academy build take?</summary><p>Academy Foundation typically takes 8–10 weeks depending on course complexity, number of modules, and how quickly content is provided for upload. A focused 8-pillar course can be live in 2–3 weeks. A multi-path academy with community features and a full launch funnel takes 8–10 weeks. Growth Engine audit and optimisation work typically produces measurable results within 30 days of implementation.</p></details><details class="card cb-q"><summary>Which programme is right for me — Foundation or Growth Engine?</summary><p>If you have no live academy yet — or have started building one but not launched — Academy Foundation is your programme. If you have a live LearnWorlds academy that is either under-enrolling, has low completion rates, or is not generating the revenue it should, Growth Engine is the correct fit. If you are genuinely unsure, book the strategy call and I will diagnose your situation and tell you directly which programme applies.</p></details><details class="card cb-q"><summary>Can you also help with marketing and selling the course — not just the technical build?</summary><p>Yes — both programmes include a launch strategy component: sales page copywriting, email launch sequence, and social media content for the launch period. For clients who want a full end-to-end marketing system — lead magnets, funnels, paid advertising, and ongoing social media management — I offer these as additional services that run alongside or after the academy build.</p></details><details class="card cb-q"><summary>Will I be able to manage the academy myself after it is built?</summary><p>Yes — every project includes a structured handover session and written documentation so you can add new lessons, update content, and manage your student community independently. LearnWorlds is designed to be operated confidently by non-technical users once it is properly set up. You own the platform, the content, and all student data outright — no ongoing dependency on me to keep it running.</p></details></div></section><section class="card cb-close"><h2 class="cb-h" style="margin:0 0 8px">Ready to build or scale your academy?</h2><p class="cb-sub" style="margin:0 0 14px">The strategy call is free and there&rsquo;s no pressure to move forward.</p><div class="cb-btns"><a class="btn cb-btn " href="https://tally.so/r/o9evD1?service=Online%20Course%20-%20Academy%20Foundation" target="_blank" rel="noopener noreferrer">Academy Foundation</a><a class="btn cb-btn " href="https://tally.so/r/o9evD1?service=Online%20Course%20-%20Academy%20Growth%20Engine" target="_blank" rel="noopener noreferrer">Academy Growth Engine (Monthly Retainer)</a></div></section>`;
const VIDEO_HERO=`<section class="card hero" style="margin-top:10px"><p class="eb">AI Video Strategy &amp; Editing</p><h1>More video. Less of your time.</h1><p class="sub">AI-powered video strategy, scripting, and editing for coaches, consultants, and business owners. Reels, TikToks, YouTube Shorts, and content repurposing &mdash; professional video output at scale, without you spending hours in front of a camera or a timeline.</p><div class="cb-btns" style="justify-content:flex-start;margin:16px 0 12px"><a class="btn cb-btn " href="https://tally.so/r/o9evD1?service=AI%20Video%20Editing%20%26%20Strategy" target="_blank" rel="noopener noreferrer">Get a free project quote</a><a class="btn cb-btn cb-alt" href="https://calendly.com/admin-taskforcezsolution-15-minute-strategic-call/15min" target="_blank" rel="noopener noreferrer">Book a Strategic Call!</a></div><ul class="cb-chips"><li>✓ Strategy + scripting + editing</li><li>✓ Camera-shy friendly options</li><li>✓ Repurpose existing content</li></ul><div class="cb-stats"><div><b>4+</b><span>Platforms in one workflow</span></div><div><b>AI-powered</b><span>Script &amp; editing workflow</span></div><div><b>Repurpose</b><span>existing content at scale</span></div><div><b>Strategy</b><span>+ scripting + editing</span></div></div></section>`;const VIDEO_BODY=`<section class="cb-sec"><h2 class="cb-h">Video is the highest-reach format on every platform. Most businesses aren't producing enough of it.</h2><p class="cb-sub">Short-form video consistently outperforms static content on reach, engagement, and follower growth. The problem is not that businesses do not know this — it is that producing great video consistently takes time and skills most business owners do not have.</p><div class="cb-grid"><div class="card cb-card"><span class="cb-ico">❎</span><h3>Video takes too long to produce</h3><p>Script, film, edit, caption, export, post — even a 30-second Reel can eat 3–4 hours when you do it yourself without a workflow.</p></div><div class="card cb-card"><span class="cb-ico">❎</span><h3>Camera anxiety kills consistency</h3><p>Most business owners avoid video not because they lack ideas — but because appearing on camera feels uncomfortable. There are formats that do not require it.</p></div><div class="card cb-card"><span class="cb-ico">❎</span><h3>Raw footage sits unwatched on a hard drive</h3><p>You record content with good intentions and then never get around to editing it. It ages. The algorithm moves on. The moment is gone.</p></div><div class="card cb-card"><span class="cb-ico">❎</span><h3>No strategy behind the content</h3><p>Posting random videos with no hook strategy, platform awareness, or repurposing plan produces random results. Volume without direction is noise.</p></div></div></section><section class="cb-sec"><p class="eb">Why AI-powered video</p><h2 class="cb-h">Professional video output. Without the production overhead.</h2><p class="cb-sub">AI tools accelerate every stage of the video workflow — from script ideation to editing — while human creative judgment ensures everything sounds and looks like you.</p><div class="cb-grid"><div class="card cb-card"><span class="cb-ico">⚡</span><h3>Faster at Every Stage</h3><p>AI-assisted scripting, auto-captioning, smart editing, and trend analysis compress what used to take hours into a fraction of the time — without sacrificing quality.</p></div><div class="card cb-card"><span class="cb-ico">🔄</span><h3>One Piece, Many Videos</h3><p>A single long-form video, podcast episode, or webinar recording becomes 8–12 short-form clips for different platforms — each optimised for its audience and format.</p></div><div class="card cb-card"><span class="cb-ico">🎭</span><h3>Camera-Shy Friendly</h3><p>AI avatars, voiceover-led videos, text-motion formats, and screen recordings produce scroll-stopping content without you ever needing to appear on camera.</p></div><div class="card cb-card"><span class="cb-ico">📈</span><h3>Algorithm-Aware Strategy</h3><p>Every video is built around what each platform's algorithm rewards right now — hook structure, caption format, hashtags, posting time, and trending audio selection.</p></div></div></section><section class="cb-sec"><p class="eb">What I produce</p><h2 class="cb-h">Eight video formats. One content workflow.</h2><p class="cb-sub">From raw footage editing to fully AI-generated video — every format serves a different business goal and audience preference.</p><div class="cb-grid"><div class="card cb-card"><span class="cb-n">01</span><h3>Instagram Reels &amp; TikTok</h3><p>Hook-first short-form video (15–60 sec) optimised for reach and follower growth — the highest-return video format for organic audience building.</p><span class="cb-tag sm" style="margin:10px 0 0">Highest organic reach</span></div><div class="card cb-card"><span class="cb-n">02</span><h3>YouTube Shorts</h3><p>Vertical short-form videos for YouTube's algorithm — building a subscriber base that compounds long-term alongside your existing content.</p></div><div class="card cb-card"><span class="cb-n">03</span><h3>LinkedIn Video</h3><p>Talking-head or text-motion video for LinkedIn's professional audience — thought leadership that drives connection requests and enquiries.</p></div><div class="card cb-card"><span class="cb-n">04</span><h3>Content Repurposing</h3><p>Turn one long-form recording — webinar, podcast, coaching call, or YouTube video — into 8–12 platform-optimised short clips automatically.</p></div><div class="card cb-card"><span class="cb-n">05</span><h3>AI Avatar Video</h3><p>Fully AI-generated videos using a digital avatar — no camera, no filming. Script it, generate it, post it. Ideal for camera-shy creators at scale.</p></div><div class="card cb-card"><span class="cb-n">06</span><h3>Voiceover &amp; Slideshow</h3><p>Narrated slide or image videos — your voice over branded visuals, captions, and motion graphics. High-value educational content without on-camera presence.</p></div><div class="card cb-card"><span class="cb-n">07</span><h3>Screen Recording &amp; Tutorial</h3><p>Software walkthroughs, tool demos, and educational tutorials — edited with branded overlays, animated callouts, and chapter markers.</p></div><div class="card cb-card"><span class="cb-n">08</span><h3>Ad Creative Video</h3><p>Short-form video ads for Facebook, Instagram, TikTok, and YouTube — hook in the first 2 seconds, offer clear, CTA compelling. Built to convert, not just inform.</p></div></div></section><section class="cb-sec"><p class="eb">What's included</p><h2 class="cb-h">Strategy to final file. All handled.</h2><p class="cb-sub">Every video project or monthly retainer covers all four phases — nothing is left half-finished or handed back for you to figure out.</p><div class="cb-grid cb-inc"><div class="card cb-card"><span class="cb-ico">🎯</span><h3>Strategy &amp; Content Planning</h3><ul class="cb-ul"><li>Video content strategy aligned to your business goals and audience</li><li>Platform selection — which formats belong on which channel</li><li>Monthly video content calendar with topics, hooks, and formats</li><li>Trend research and algorithm-aware scheduling recommendations</li><li>Repurposing plan — mapping existing content to short-form clips</li><li>Competitor video analysis and content gap identification</li></ul></div><div class="card cb-card"><span class="cb-ico">✍️</span><h3>Scripting &amp; Copywriting</h3><ul class="cb-ul"><li>Hook writing — the first 2 seconds that stop the scroll</li><li>Full video scripts written in your voice and pacing</li><li>Caption and on-screen text written for readability</li><li>Auto-caption review and correction for accuracy</li><li>Hashtag research and platform-specific copy optimisation</li><li>CTA scripting — driving comments, saves, clicks, or DMs</li></ul></div><div class="card cb-card"><span class="cb-ico">✂️</span><h3>Editing &amp; Production</h3><ul class="cb-ul"><li>Raw footage editing — cuts, pacing, and flow optimisation</li><li>Captions, subtitles, and animated text overlays</li><li>B-roll sourcing and integration</li><li>Branded lower thirds, intros, and outro cards</li><li>Trending audio selection and sync</li><li>Format export for each platform (9:16, 16:9, 1:1)</li></ul></div><div class="card cb-card"><span class="cb-ico">📊</span><h3>Delivery &amp; Optimisation</h3><ul class="cb-ul"><li>All final video files delivered in platform-ready formats</li><li>Thumbnail design for YouTube and video post covers</li><li>Posting support and scheduling assistance</li><li>Monthly performance review — views, reach, saves, follows</li><li>A/B hook testing recommendations based on performance data</li><li>Monthly content adjustments based on what is working</li></ul></div></div></section><section class="cb-sec"><h2 class="cb-h">How the AI workflow actually works.</h2><p class="cb-sub">Four stages — each one accelerated by AI tools, each one quality-checked by human judgment. Speed without sacrificing authenticity.</p><div class="cb-grid"><div class="card cb-card"><span class="cb-n">01</span><h3>AI-Assisted Strategy</h3><p>Trend scanning, topic ideation, hook frameworks, and audience research — done in minutes, not days. Every video starts with a data-backed reason to exist.</p></div><div class="card cb-card"><span class="cb-n">02</span><h3>Script &amp; Hook Writing</h3><p>AI drafts the structure and hook options. Human creative judgment selects, rewrites, and voices the final script in your authentic tone.</p></div><div class="card cb-card"><span class="cb-n">03</span><h3>AI-Accelerated Editing</h3><p>Auto-caption generation, smart cut detection, background noise removal, and colour correction — AI handles the repetitive work while creative decisions stay human.</p></div><div class="card cb-card"><span class="cb-n">04</span><h3>Multi-Platform Export</h3><p>Each video is formatted, captioned, and optimised for every target platform — the right aspect ratio, the right length, the right caption style. One shoot, many outputs.</p></div></div></section><section class="cb-sec"><p class="eb">How it works</p><h2 class="cb-h">Brief to published video in five steps.</h2><p class="cb-sub">A clear, repeatable process so every batch of videos is delivered on time, on brand, and ready to post — with zero chasing.</p><div class="cb-grid"><div class="card cb-card"><span class="cb-ico">1️⃣</span><h3>Strategy Session</h3><p>I define your audience, video goals with you, platform priorities, and content pillars. No guessing — every video has a purpose.</p></div><div class="card cb-card"><span class="cb-ico">2️⃣</span><h3>Script &amp; Brief</h3><p>Scripts or shot briefs are written and shared for approval before any filming or editing begins. You know exactly what each video will say.</p></div><div class="card cb-card"><span class="cb-ico">3️⃣</span><h3>Record or Source</h3><p>You film using the brief (if on-camera content) or provide existing footage — or I source everything needed for camera-free formats.</p></div><div class="card cb-card"><span class="cb-ico">4️⃣</span><h3>Edit &amp; Review</h3><p>Videos are edited, captioned, and formatted. You review the batch and request any adjustments before final export.</p></div><div class="card cb-card"><span class="cb-ico">5️⃣</span><h3>Deliver &amp; Post</h3><p>Final files delivered in all required formats. Posting support and scheduling assistance included. Performance reviewed monthly.</p></div></div></section><section class="cb-sec"><p class="eb">Common questions</p><h2 class="cb-h">Answered before you ask.</h2><div class="cb-faq"><details class="card cb-q"><summary>Do I need to appear on camera?</summary><p>No — camera-shy clients are very welcome. Several of the video formats I produce require zero on-camera presence: AI avatar video, voiceover-led slideshow video, screen recordings, text-motion graphics, and repurposed content from podcasts or webinars. I will discuss which formats make the most sense for your business and your comfort level during the strategy session.</p></details><details class="card cb-q"><summary>What if I already have existing footage I have never edited?</summary><p>Existing footage is ideal — it means I can start producing content immediately without any new filming. Send me whatever you have: phone recordings, webinar recordings, Zoom calls, podcast episodes, conference presentations, or old YouTube videos. I will identify the best clips, edit them into short-form content, and optimise each one for the platform it will live on.</p></details><details class="card cb-q"><summary>How many videos do I get per month?</summary><p>This depends on your package. A standard monthly video retainer covers 8–12 short-form videos across your active platforms, including scripting, editing, captions, and platform optimisation. Projects are also available if you want a specific batch of videos without a monthly commitment — for example, 6 videos for a launch campaign or 10 clips from a single recording.</p></details><details class="card cb-q"><summary>What format do I need to send my raw footage in?</summary><p>Any standard format works: MP4, MOV, or AVI. Phone-recorded footage is perfectly fine — most modern phone cameras produce high enough quality for social media video. If you are filming yourself, I will provide a simple filming brief that takes most clients under 10 minutes per video. No professional equipment required.</p></details><details class="card cb-q"><summary>Will the videos actually sound like me?</summary><p>Yes — voice and tone matching is a core part of the scripting process. All scripts are written after a voice discovery session where I study how you naturally speak and communicate. AI tools are used for speed and structure, but all final scripts are written and reviewed by a human to ensure they sound like you — not like a generic AI output.</p></details><details class="card cb-q"><summary>Can you handle posting and scheduling as well as editing?</summary><p>Posting and scheduling support is included in monthly retainers. I prepare the caption, select the hashtags, recommend the posting time, and either post directly or prepare everything in a scheduling tool for your approval. You are involved for any final approval — nothing goes live without your sign-off unless you specifically request fully delegated posting.</p></details></div></section><section class="card cb-close"><p class="eb" style="margin-bottom:12px">Ready to start</p><h2 class="cb-h" style="margin:0 auto 8px">Your audience is watching video. Let&rsquo;s give them yours.</h2><p class="cb-sub" style="margin:0 auto 16px">Tell me what you have &mdash; existing footage, a podcast, a product, an idea &mdash; and I will quote you a video content system that fits your time, your budget, and your goals.</p><div class="cb-btns"><a class="btn cb-btn " href="https://tally.so/r/o9evD1?service=AI%20Video%20Editing%20%26%20Strategy" target="_blank" rel="noopener noreferrer">Get a free project quote</a><a class="btn cb-btn cb-alt" href="https://calendly.com/admin-taskforcezsolution-15-minute-strategic-call/15min" target="_blank" rel="noopener noreferrer">Book a Strategic Call!</a></div><div style="margin-top:16px"><ul class="cb-chips"><li>✓ Strategy + scripting + editing</li><li>✓ No camera required</li><li>✓ Repurpose existing content</li><li>✓ AI-powered, human-quality</li></ul></div></section>`;
