function enhanceSvc(h){
 const k=h.startsWith("svc-")?h.slice(4):"",main=document.querySelector("main");if(!main||!PAGES[k])return;
 // 1) emoji -> designed SVG icons
 main.querySelectorAll(".cb-ico").forEach(el=>{const t=el.textContent.trim();
  if(/^[0-9]/.test(t)){el.classList.add("num");el.innerHTML="<b>"+t[0]+"</b>"}
  else{const n=UIEMO[t]||UIEMO[t.replace(/\uFE0F/g,"")]||"sparkles";el.innerHTML=uiI(n);if(n==="x")el.classList.add("bad")}});
 main.querySelectorAll(".cb-chips li").forEach(li=>{li.innerHTML=uiI("check")+"<span>"+li.textContent.replace(/^[✓✔]\s*/,"")+"</span>"});
 main.querySelectorAll(".cb-n").forEach(el=>el.classList.add("nn"));
 // 2) modern hero (centered serif headline, pill buttons, fanned cards)
 const old=main.querySelector(".hero");
 if(old){const g=q=>old.querySelector(q),eb=g(".eb"),h1=g("h1"),sub=g(".sub"),btns=[...old.querySelectorAll("a.btn")],stats=[...old.querySelectorAll(".cb-stats>div")].map(d=>[d.querySelector("b").textContent,d.querySelector("span").textContent]);
  const chips=[...old.querySelectorAll(".cb-chips li")].map(l=>l.textContent.trim()),note=g(".cb-note");
  const trust=chips.length?chips.join("  ·  "):(note?note.textContent:"");
  const how=[...main.querySelectorAll(".cb-sec .eb")].find(e=>/how it works/i.test(e.textContent));
  const target=how?how.closest(".cb-sec"):main.querySelectorAll(".cb-sec")[3]||main.querySelector(".cb-sec");target&&(target.id="cb-how");
  let cards=[];const imgs=PROJECTS[k]||[];
  if(k=="course"&&imgs.length)cards=[3,4,1].map(i=>({img:imgs[i],fit:"contain"}));
  else if(k=="social"&&imgs.length>2)cards=[1,0,2].map(i=>({img:imgs[i],fit:"cover"}));
  else if(k=="video"&&imgs.length>2){cards=[0,3,5].map(i=>{const m=/poster="([^"]+)"/.exec(imgs[i]||"");return{img:m&&m[1],fit:"cover"}})}
  else cards=stats.slice(0,3).map((st,i)=>({stat:st,icon:["timer","layers","sparkles"][i],ix:i}));
  if(cards.length==3&&!cards[1].stat){}
  const order=cards.length==3&&cards[0].stat?[0,1,2]:[0,1,2];
  const fan=cards.map((c,i)=>c.img?`<div class="mh-c c${i}"><img src="${c.img}" alt="" style="object-fit:${c.fit}" draggable="false"></div>`:`<div class="mh-c c${i} mh-stat"><span class="mh-i">${uiI(c.icon)}</span><b>${c.stat[0]}</b><em>${c.stat[1]}</em></div>`).join("");
  const so={course:[["Strategy","+ design + build in one"],["Global","Coaches & course creators"],["Build","or audit & scale \u2014 both covered"]],social:[["30+","Posts per month per client"],["6.4%","Avg engagement rate achieved"],["AI-powered","Content creation workflow"]],video:[["AI-powered","Script & editing workflow"],["Repurpose","existing content at scale"],["Strategy","+ scripting + editing"]]}[k];const tail=so?`<div class="mh-stats">${so.map(a=>`<div><b>${a[0]}</b><span>${a[1]}</span></div>`).join("")}</div>`:`<div class="mh-fan">${fan}</div>`;const sec=document.createElement("section");sec.className="mh";
  sec.innerHTML=`<p class="mh-eb"><i></i>${eb?eb.textContent:""}</p><h1>${h1.textContent}</h1><p class="mh-sub">${sub.textContent}</p><div class="mh-btns"><a class="mh-b dark" href="${btns[0]?btns[0].href:"#"}" target="_blank" rel="noopener noreferrer">${btns[0]?btns[0].textContent:"Get started"}</a><a class="mh-b light" href="#cb-how" data-go="cb-how">${how?"How it works":"See what\u2019s included"}</a></div><p class="mh-trust">${trust}</p>${tail}`;
  old.replaceWith(sec)}
 // 3) section layouts
 main.querySelectorAll(".cb-sec").forEach(sec=>{
  const eb=(sec.querySelector(".eb")||{}).textContent||"",grid=sec.querySelector(":scope>.cb-grid"),inc=sec.querySelector(":scope>.cb-inc"),faq=sec.querySelector(":scope>.cb-faq");
  const wrap=cls=>{const l=document.createElement("div");l.className="sp-l";[...sec.children].filter(c=>!c.matches(".cb-grid,.cb-faq,.cb-tw,.cb-tabs,.cb-close")).forEach(c=>l.appendChild(c));const r=document.createElement("div");r.className="sp-r";[...sec.children].forEach(c=>r.appendChild(c));sec.append(l,r);sec.classList.add(cls)};
  if(inc){const cs=[...inc.children],tabs=document.createElement("div");tabs.className="cb-tabs";
   tabs.innerHTML=`<div class="cb-tn" role="tablist">${cs.map((c,i)=>`<button type="button" role="tab" class="${i?"":"on"}" data-i="${i}"><span class="cb-ico">${c.querySelector(".cb-ico")?c.querySelector(".cb-ico").innerHTML:uiI(["compass","palette","blocks","rocket","book-open","trending-up"][i%6])}</span><span>${c.querySelector("h3").textContent}</span></button>`).join("")}</div><div class="cb-tp">${cs.map((c,i)=>`<div class="pn${i?"":" on"}" role="tabpanel"><h3>${c.querySelector("h3").innerHTML}</h3>${c.querySelector("ul").outerHTML}</div>`).join("")}</div>`;
   inc.replaceWith(tabs);sec.classList.add("cs-tabsec");return}
  if(faq){wrap("cs-faqs");return}
  if(grid){const n=grid.children.length,numeric=[...grid.children].every(c=>c.querySelector(".cb-ico.num")),bad=grid.querySelector(".cb-ico.bad");
   grid.dataset.n=n;
   if(bad){wrap("cs-split");grid.classList.add("pb");return}
   if(/^why /i.test(eb)){sec.classList.add("cs-bento");return}
   if(numeric||(/how it works/i.test(eb))||[...grid.children].every(c=>c.querySelector(".cb-tag.sm")&&/^Stage/.test(c.querySelector(".cb-tag.sm").textContent))||(!eb&&[...grid.children].every(c=>c.querySelector(".nn"))&&n<=5)){grid.classList.add("cs-tl");sec.classList.add("cs-tlsec");return}
   if(/the real problem/i.test(eb)){wrap("cs-split");grid.classList.add("pb");return}
   sec.classList.add("cs-tiles")}});
 // closing banner gets a strategy-call button on the website page
 if(k=="website"){const c=main.querySelector(".cb-close:last-of-type .cb-btns");if(c&&!c.querySelector("a[href*=calendly]"))c.insertAdjacentHTML("beforeend",`<a class="btn cb-btn cb-alt" href="https://calendly.com/admin-taskforcezsolution-15-minute-strategic-call/15min" target="_blank" rel="noopener noreferrer">Book a Strategic Call Now!</a>`)}
}
document.addEventListener("click",e=>{
 const t=e.target.closest(".cb-tn button");if(t){const w=t.closest(".cb-tabs"),i=t.dataset.i;w.querySelectorAll(".cb-tn button").forEach(b=>b.classList.toggle("on",b===t));w.querySelectorAll(".pn").forEach((p,j)=>p.classList.toggle("on",j==i));return}
 const g=e.target.closest("[data-go]");if(g){e.preventDefault();const el=document.getElementById(g.dataset.go);el&&el.scrollIntoView({behavior:"smooth",block:"start"})}});
// Back to top (glide + arrow loop), all pages
(()=>{const b=document.createElement("button");b.type="button";b.className="bt-top";b.setAttribute("aria-label","Back to top");b.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M12 19V5M5 12l7-7 7 7"/></svg>';document.body.appendChild(b);
 let glide=null;const ease=x=>x<.5?4*x*x*x:1-Math.pow(-2*x+2,3)/2;
 const step=t=>{if(!glide)return;const k=Math.min(1,(t-glide.t0)/glide.d);window.scrollTo({top:glide.from*(1-ease(k)),left:0,behavior:"instant"});b.classList.toggle("go",k<1);if(k>=1)glide=null;else requestAnimationFrame(step)};
 b.addEventListener("click",()=>{glide={from:window.scrollY,t0:performance.now(),d:1000};requestAnimationFrame(step)});
 const sh=()=>b.classList.toggle("show",window.scrollY>40);addEventListener("scroll",sh,{passive:true});sh()})();

